"""W73 through the real dock on Bidah: the Basin points layer, its clicks and the delineation ticks, generated by the real
engine each time.

Bidah 03's ground and dam (W27's set-up), a 2 km2 threshold. A plain generation first; then a new Basin points layer
from the box's button, points placed by the box's own map tool (a click is the tool's signal, as the canvas sends it):
a junction on a reach, a join at a confluence, a removal of another confluence, a source with a CSV hydrograph; and a
wall layer with the Walls tick on and off.
"""

import json

THRESHOLD_KM2 = 2.0


def by_kind(model, kind):
    return [e for e in model["elements"] if e["kind"] == kind]


def local_subbasins(model, name):
    return [e for e in by_kind(model, "subbasin") if e["downstream"] == name]


def scenario(h):
    from pathlib import Path

    from qgis.core import QgsPointXY, QgsProject
    from qgis.PyQt.QtCore import QCoreApplication, Qt

    h.VENV = Path(r"D:\Mojtaba\Renardet\Wadi2D\.venv\Scripts\python.exe")  # a worktree has no venv of its own
    ground = h.Bidah()
    dam = json.loads((h.VALIDATION / "jobs" / "dam_Bidah03_100yr_20.json").read_text(encoding="utf-8"))
    crests = [o for o in dam["terrain"]["objects"] if o["kind"] == "crest_line"]
    longest = max(crests, key=lambda o: len(o["coordinates"]))
    crest = h.add_vector(
        h.geojson("crest", [h.line(o["coordinates"], z=o["z_constant"], name="Bidah 03" if o is longest else f"saddle {n}")
                            for n, o in enumerate(crests, 1)]),
        "crest", ground.crs,
    )  # fmt: skip
    dock = yield from h.open_dock()
    hy, box, s = dock.hydrology, dock.hydrology.basin, dock.structures
    h.set_rain_job(dock, ground, "basin_points", dx=20.0, rain=60.0, hours=1.0, sim_hours=1.0, pixels=False)
    s.layers["crest_line"].setLayer(crest)
    s.fields["crest_line"]["crest_z"].setField("z")
    box.setChecked(True)
    box.threshold.setValue(THRESHOLD_KM2)

    def generate():
        old = box.model
        box.generate_button.click()
        yield lambda: box.generate_button.isEnabled()
        h.log(f"summary: {box.summary.text()[:300]}")
        h.check("generated by the engine", box.model is not None and box.model is not old, box.summary.text()[:300])
        return box.model

    h.log("=== 1 the box: points row, kinds, ticks")
    kinds = [box.point_kind.itemData(i) for i in range(box.point_kind.count())]
    from wadi2d_qgis.basin_point_rows import POINT_KINDS

    h.check("the eight kinds are offered", kinds == list(POINT_KINDS), kinds)
    h.check("walls and burn lines ticked, the rest not", {k for k, b in box.ticks.items() if b.isChecked()} == {"wall", "burn_line"})
    plain = yield from generate()
    h.check("a plain basin", plain is not None and len(by_kind(plain, "subbasin")) >= 3, box.summary.text())
    subs0 = len(by_kind(plain, "subbasin"))

    h.log("=== 2 a new Basin points layer from the button")
    box.new_points_button.click()
    QCoreApplication.processEvents()
    layer = box.pour.currentLayer()
    h.check("the layer is the box's choice, with the kind field", layer is not None and "kind" in layer.fields().names())
    node = QgsProject.instance().layerTreeRoot().findLayer(layer.id()) if layer else None
    parent = node.parent().name() if node else None
    h.check("it sits in Inputs > Hydrology", parent == "Hydrology", parent)

    def click(kind, x, y):
        box.point_kind.setCurrentIndex(box.point_kind.findData(kind))
        box.place_button.setChecked(True)
        QCoreApplication.processEvents()
        tool = dock.basin_points.tool
        h.check(f"{kind}: the map tool is on", dock.iface.mapCanvas().mapTool() is tool)
        tool.canvasClicked.emit(QgsPointXY(x, y), Qt.LeftButton)
        QCoreApplication.processEvents()
        h.check(f"{kind}: the button is up again and the box says it", not box.place_button.isChecked() and "Generate basin" in box.summary.text(), box.summary.text())

    h.log("=== 3 a junction on a reach splits it")
    reaches = [la for la in QgsProject.instance().mapLayersByName("Reaches, generated")]
    line = max(reaches[0].getFeatures(), key=lambda f: f.geometry().length()).geometry()
    mid = line.interpolate(line.length() / 2.0).asPoint()
    click("junction", mid.x(), mid.y())
    split = yield from generate()
    h.check("one subbasin more", len(by_kind(split, "subbasin")) == subs0 + 1, (subs0, len(by_kind(split, "subbasin"))))
    h.check("the point names its junction", any(e["name"] == "Junction 1" for e in split["elements"]), [e["name"] for e in by_kind(split, "junction")])
    h.check("the points layer survives the regeneration", box.pour.currentLayer() is layer)

    h.log("=== 4 join the subbasins at a confluence")
    confluences = [e for e in by_kind(split, "junction") if len(local_subbasins(split, e["name"])) >= 2 and "pour_point" not in e]
    h.check("a confluence with two local subbasins", bool(confluences))
    target = confluences[0]
    before = sum(e["parameters"]["area_km2"]["value"] for e in local_subbasins(split, target["name"]))
    click("join_subbasins", *target["outlet"])
    joined = yield from generate()
    local = local_subbasins(joined, target["name"])
    h.check("one subbasin there now", len(local) == 1, [e["name"] for e in local])
    h.check("with the area of the two", local and abs(local[0]["parameters"]["area_km2"]["value"] - before) < 1e-3, (before, local and local[0]["parameters"]["area_km2"]))

    h.log("=== 5 remove another confluence")
    others = [e for e in by_kind(joined, "junction") if e["name"] != target["name"] and "pour_point" not in e and e["downstream"]]
    upstream = [e for e in others if sum(1 for x in joined["elements"] if x["downstream"] == e["name"] and x["kind"] == "reach") >= 1]
    gone = (upstream or others)[0]
    click("remove_junction", *gone["outlet"])
    removed = yield from generate()
    names = {e["name"] for e in removed["elements"]}
    h.check("the junction is gone", gone["name"] not in names, gone["name"])
    total = lambda m: sum(e["parameters"]["area_km2"]["value"] for e in by_kind(m, "subbasin"))  # noqa: E731
    h.check("the subbasins cover the same ground", abs(total(removed) - total(joined)) < 1e-3, (total(joined), total(removed)))

    h.log("=== 6 a source with its hydrograph")
    csv = h.DATA / "inflow.csv"
    csv.write_text("minutes,flow\n0,0\n60,40\n240,0\n", encoding="utf-8")
    click("source", mid.x(), mid.y())
    feature = max(layer.getFeatures(), key=lambda f: f.id())
    layer.dataProvider().changeAttributeValues({feature.id(): {layer.fields().indexOf("file"): str(csv)}})
    sourced = yield from generate()
    sources = by_kind(sourced, "source")
    h.check("a source element", len(sources) == 1 and sources[0]["name"] == "Source 1", [e["name"] for e in sources])
    h.check("it enters at Junction 1", sources and sources[0]["downstream"] == "Junction 1", sources and sources[0]["downstream"])
    h.check("basin.json carries the hydrograph", sources and sources[0]["parameters"]["hydrograph"]["value"]["flow_m3s"] == [0.0, 40.0, 0.0])

    h.log("=== 7 a wall with the Walls tick, then without")
    x0, y0, x1, y1 = mid.x() - 300.0, mid.y() - 300.0, mid.x() + 300.0, mid.y() + 300.0
    wall = h.add_vector(h.geojson("wall", [h.line([[x0, y0], [x1, y1]], name="W test")]), "wall", ground.crs)
    s.layers["wall"].setLayer(wall)
    walled = yield from generate()
    h.check("the note names the wall", any("delineated with W test" in n for n in walled["notes"]), walled["notes"][-3:])
    box.ticks["wall"].setChecked(False)
    unwalled = yield from generate()
    h.check("untick: no wall in the delineation", not any("delineated with" in n for n in unwalled["notes"]), unwalled["notes"][-3:])
    job = json.loads((Path(box.json_path).parent / "job.json").read_text(encoding="utf-8"))
    h.check("the job says delineate false on the wall", [o.get("delineate") for o in job["terrain"]["objects"] if o["kind"] == "wall"] == [False])
    h.widget_shot("basin_box", box)
